def solve(transactions, start):
    balance = start
    for tx in transactions:
        if tx["type"] == "credit":
            balance += tx["amount"]
        elif tx["type"] == "debit":
            if tx["amount"] <= balance:
                balance -= tx["amount"]
    return balance


